commands:
Bash: git worktree add -q .claude/worktrees/rv14 rv14 && W=$PWD/.claude/worktrees/rv14 && cd $W && tsc --noEmit --strict --target es2020 --module esnext --moduleResolution bundler --lib es2020,dom src/*.ts src/utils/*.ts; echo "tsc exit $?"; mkdir -p /tmp/rv14-check && cat > /tmp/rv14-check/check.ts <<EOF
const store = new Map<string, string>();
(globalThis as any).localStorage = { getItem: (k: string) => store.get(k) ?? null, setItem: (k: string, v: string) => { store.set(k, v); } };
const { renameWallet } = await import("$W/src/rename-wallet.ts");
try { await renameWallet("w1", "  New   Name ", async () => { throw new Error("save failed"); }); } catch (e) { console.log("save threw:", (e as Error).message); }
console.log("history after failed save:", store.get("wallet-rename-history:w1"));
store.set("wallet-rename-history:w2", "not json");
let saved = false;
try { await renameWallet("w2", "Ok", async () => { saved = true; }); } catch (e) { console.log("corrupt history threw:", (e as Error).message); }
console.log("save called with corrupt history:", saved);
let savedName = "unset";
await renameWallet("w3", "   ", async (_id, n) => { savedName = n; });
console.log("blank input saved as:", JSON.stringify(savedName));
await renameWallet("w4", "x".repeat(45), async (_id, n) => { savedName = n; });
console.log("45-char input saved length:", savedName.length);
EOF
cd /tmp/rv14-check && bun run check.ts
